 q('#massUpdateBtn',z).onclick=async e=>{const f=await dialog('Mass update canonical term',[{id:'from',label:'Current name / term'},{id:'to',label:'Canonical replacement'},{id:'caseSensitive',label:'Match case exactly',type:'checkbox',value:false}],'Review changes');if(!f?.from||!f.to)return;const [nodes,entities,timeline,threads,rules]=await Promise.all([svc.projectCall('nodes.list',{}).then(r=>r.nodes||[]),svc.projectCall('entities.list',{}).then(r=>r.entities||[]),svc.projectCall('timeline.list',{}).then(r=>r.events||[]),svc.projectCall('story.threads.list',{}).then(r=>r.threads||[]),svc.projectCall('story.rules.list',{}).then(r=>r.rules||[])]);const flags=f.caseSensitive?'g':'gi',rx=new RegExp(String(f.from).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),flags),rep=v=>typeof v==='string'?v.replace(rx,f.to):v,deep=v=>Array.isArray(v)?v.map(deep):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,deep(x)])):rep(v);const muts=[];nodes.forEach(n=>{const title=rep(n.title||''),content=rep(n.content||''),plainText=rep(n.plainText||'');if(title!==n.title||content!==n.content||plainText!==n.plainText)muts.push({type:'node-update',id:n.id,title,content,plainText,metadata:deep(n.metadata||{})});});entities.forEach(x=>{const d=deep(x);if(JSON.stringify(d)!==JSON.stringify(x))muts.push({type:'entity-update',id:x.id,data:d});});timeline.forEach(x=>{const d=deep(x);if(JSON.stringify(d)!==JSON.stringify(x))muts.push({type:'timeline-save',data:d});});threads.forEach(x=>{const d=deep(x);if(JSON.stringify(d)!==JSON.stringify(x))muts.push({type:'thread-save',data:d});});rules.forEach(x=>{const d=deep(x);if(JSON.stringify(d)!==JSON.stringify(x))muts.push({type:'world-rule-save',data:d});});if(!muts.length){toast('No matching canonical term was found.','warning');return;}const ok=await LF.dialog({title:'Mass update review',body:`<p>${muts.length} connected record${muts.length===1?'':'s'} will be updated. A revision snapshot will be created first.</p>`,confirmText:'Apply update',cancelText:'Cancel'});if(ok)await run(e.target,()=>svc.projectCall('bulk.apply',{mutations:muts,reason:`Canonical term update: ${f.from} → ${f.to}`}),`${muts.length} records updated.`);};
