async function ensureGoogleIdentity(){if(global.google?.accounts?.id)return;await new Promise((resolve,reject)=>{const old=document.querySelector('script[data-literary-google]');if(old){if(global.google?.accounts?.id)return resolve();old.addEventListener('load',resolve,{once:true});old.addEventListener('error',reject,{once:true});return;}const el=document.createElement('script');el.src='https://accounts.google.com/gsi/client';el.async=true;el.defer=true;el.dataset.literaryGoogle='1';el.onload=resolve;el.onerror=reject;document.head.appendChild(el);});}
async function linkGoogleAccount(){const cfg=await svc.call('client.config',{}, {token:''});if(!cfg.googleClientId)throw new Error('Google account linking is not available right now.');await ensureGoogleIdentity();return new Promise((resolve,reject)=>{global.google.accounts.id.initialize({client_id:cfg.googleClientId,callback:async r=>{try{if(!r?.credential)throw new Error('Google account selection was cancelled.');resolve(await svc.call('auth.google.link',{credential:r.credential}));}catch(e){reject(e);}}});global.google.accounts.id.prompt(n=>{if(n.isNotDisplayed?.()||n.isSkippedMoment?.())reject(new Error('Choose Link Google again and allow the account chooser.'));});});}
